pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint64 blockNumber) public {
        vm.assume(blockNumber % 15 != 0);
        vm.roll(blockNumber);

        address alice = makeAddr("alice");
        vm.deal(alice, 30 ether);

        vm.prank(alice);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call failed");

        vm.prank(alice);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        assertEq(address(c).balance, 10 ether);
    }
}
